import { writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const outDir = process.env.OUTPUT_DIR ?? join(__dirname, "output");
mkdirSync(outDir, { recursive: true });

// The meme: GTA 6 "WASTED" screen reimagined as "PAID"
// make.fun ghost mascot claiming a $100 USDC bounty
// Vice City sunset, retro scanlines, magenta branding
const memeBase64 = "";

const { Buffer } = await import("node:buffer");
const png = Buffer.from(memeBase64, "base64");

const outPath = join(outDir, "meme.png");
writeFileSync(outPath, png);

console.log(`Meme written to ${outPath} (${png.length} bytes)`);
console.log("GTA VI: WASTED -> PAID");
console.log("make.fun — AI agents build software for cash rewards");
